<script setup>import{ref,onMounted}from'vue';import api from'../services/api.js';import PageHero from'../components/PageHero.vue';import{Calendar,Wallet,Location,CopyDocument}from'@element-plus/icons-vue';const routes=ref([]),loading=ref(true);onMounted(async()=>{try{routes.value=await api.get('/public/routes')}finally{loading.value=false}})</script>
<template><PageHero image="/uploads/demo/banners/banner-005.png" eyebrow="ITINERARIES" title="把想去的地方，排成一条顺路的线" subtitle="每条路线都按天拆分时间、交通与费用；收藏或复制后，再改成自己的节奏。"/><div class="container routes-page"><div v-loading="loading" class="routes-grid"><router-link v-for="route in routes" :key="route.id" :to="`/route/${route.id}`" class="route"><img :src="route.coverImage"><div class="route-copy"><p>{{route.season}} · {{route.audience}}</p><h2>{{route.name}}</h2><div><span><el-icon><Calendar/></el-icon>{{route.totalDays}} 天</span><span><el-icon><Wallet/></el-icon>¥{{Number(route.budget).toLocaleString()}}</span><span><el-icon><Location/></el-icon>{{route.startPoint}}</span></div><small><el-icon><CopyDocument/></el-icon>{{route.favoriteCount}} 人收藏过这条路线</small></div></router-link></div></div></template>
<style scoped>.routes-page{padding:45px 0 80px}.routes-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}.route{background:white;border:1px solid #dfe8e7;border-radius:18px;overflow:hidden;display:grid;grid-template-columns:44% 1fr;min-height:260px;transition:.25s}.route:hover{transform:translateY(-4px);box-shadow:0 18px 40px rgba(20,65,72,.1)}.route>img{width:100%;height:100%;object-fit:cover}.route-copy{padding:25px}.route-copy>p{color:#167c8c;font-size:11px;font-weight:700}.route h2{font-family:Georgia,"Songti SC",serif;font-size:23px;line-height:1.5}.route-copy>div{display:flex;gap:12px;flex-wrap:wrap;font-size:11px;color:#657e83}.route-copy span,.route-copy small{display:flex;gap:4px;align-items:center}.route-copy small{margin-top:28px;color:#91a0a2}@media(max-width:850px){.routes-grid{grid-template-columns:1fr}}@media(max-width:500px){.route{grid-template-columns:1fr}.route>img{height:210px}.route-copy{padding:19px}}</style>

